const fcData=[{"w":"El frontend de M.E.T.A.S","a":"🗺️ Un <strong>index.html</strong> con 13 vistas, <strong>57 misiones</strong> que repiten el mismo molde, <strong>7 herramientas</strong> docentes y unas pocas <strong>capas comunes</strong>. No hay framework: hay convención."},{"w":"index.html","a":"🏠 La <strong>aplicación entera</strong> en un archivo: 13 <code>&lt;div class=\"view\"&gt;</code> que se muestran y ocultan. Cambiar de pantalla no recarga la página, solo activa otra vista."},{"w":"switchView()","a":"🔀 La función de <strong>js/app.js</strong> que apaga la vista activa y enciende otra. Es todo el \"enrutador\" del proyecto: sin librería, sin URL que recargue."},{"w":"Vista (view)","a":"🪟 Un bloque del index con <code>id=\"view-…\"</code>. Las 13: inicio, misiones, rutas, progreso, ajustes, padre, perfil (Zona Docente), admin (Mi aula), gobierno, plan-accion, parte-mensual, campeonismo y collage."},{"w":"El molde de 3 archivos","a":"📐 Cada misión vive en <code>misiones/&lt;carpeta&gt;/</code> con <strong>tres</strong>: el HTML, <code>js/&lt;mision&gt;.js</code> y <code>css/&lt;mision&gt;.css</code>. Las traducidas suman un cuarto: <code>&lt;mision&gt;-en.js</code>."},{"w":"Las 14 secciones","a":"🧩 Aprende, Estructura, Laboratorio, Flashcards, Quiz, Clasifica, Identifica, Completa, Widgets, Reto, Sopa, Tareas, Evaluación y Recursos. Idénticas en las 57: por eso reparar una enseña a reparar todas."},{"w":"js/tools/","a":"🧰 Las <strong>7 herramientas</strong> del maestro: plan-accion, registros-admin (Mi aula), campeonismo, gobierno-escolar, parte-mensual, collage-maker y pwa-install. Cada una se carga dentro de su vista."},{"w":"Capas comunes (js/)","a":"🧱 Lo que todos comparten: <strong>app.js</strong> (navegación y catálogo), metas-registro, metas-dialogos, metas-presentacion, metas-supabase, metas-docente-sync y metas-i18n."},{"w":"js/data/","a":"🗃️ Los <strong>8 bancos de datos</strong> del sistema: misiones.js (el catálogo), campeonismo-bank, dcnb-map, diagnosticos, consejos-padres, frases, paises y proceres. Datos separados de la lógica."},{"w":"misiones.js","a":"📇 El <strong>catálogo</strong>: una línea por misión con id, título, materia, ciclo, ruta, XP e ícono. Si una misión no está aquí, para la app no existe, aunque su carpeta esté completa."},{"w":"Páginas satélite","a":"🛰️ Fuera del index viven padres.html, panel-docente.html, consulta-nube.html, registro.html, camp-vivo.html, evaluaciones.html y mision.html: entradas propias para públicos distintos."},{"w":"Fichas","a":"🖨️ <code>fichas/</code> guarda una <strong>ficha imprimible por misión</strong> (57), más su índice y el mapa curricular DCNB. Es el puente entre la pantalla y el cuaderno."},{"w":"metas-i18n.js","a":"🌐 El motor de idioma: traduce rótulos comunes por diccionario y deja que cada misión traiga su <code>-en.js</code> de autor. Hoy lo cargan 8 misiones y sus fichas."},{"w":"sw.js y ?v=","a":"🔄 El service worker cachea el sitio con un nombre de versión (<strong>meta-app-v47</strong>) y los scripts se piden con <code>?v=47</code>. Subir ese número es lo que hace llegar un cambio a los teléfonos."},{"w":"¿Por qué sin framework?","a":"🎯 Sin build step, sin dependencias que caducan, imprime y carga en escuelas con internet pobre, y lo mantiene <strong>una sola persona</strong>. El costo asumido: la convención la sostiene la disciplina, no un compilador."},{"w":"Convención sobre configuración","a":"📏 Nadie obliga a que las 57 misiones se parezcan: lo hace la <strong>plantilla</strong> (PLANTILLA-MISIONES.md) y los arneses que verifican el molde. La uniformidad es una decisión, no un accidente."}];
let fcIdx=0;
function upFC(){document.getElementById('fcInner').classList.remove('flipped');document.getElementById('fcW').textContent=fcData[fcIdx].w;document.getElementById('fcA').innerHTML=fcData[fcIdx].a;document.getElementById('fcCtr').textContent=(fcIdx+1)+' / '+fcData.length;}
function flipCard(){sfx('flip');document.getElementById('fcInner').classList.toggle('flipped');if(!xpTracker.fc.has(fcIdx)){xpTracker.fc.add(fcIdx);pts(1);}if(xpTracker.fc.size===fcData.length){fin('s-flash');unlockAchievement('flash_master');}}
function nextFC(){sfx('click');fcIdx=(fcIdx+1)%fcData.length;upFC();}
function prevFC(){sfx('click');fcIdx=(fcIdx-1+fcData.length)%fcData.length;upFC();}

