const qzData=[{"q":"¿Cuántas vistas tiene index.html y cómo se cambia entre ellas?","o":["a) Una página por vista, con recarga completa","b) Un router de una librería externa","c) Cada vista es un iframe","d) 13 vistas en el mismo archivo: switchView() apaga una y enciende otra"],"c":3},{"q":"¿Qué archivos componen el molde de una misión?","o":["a) Un solo HTML gigante","b) HTML, JS y CSS propios de la misión (más el -en.js si está traducida)","c) HTML y una plantilla del servidor","d) Un JSON que la app interpreta"],"c":1},{"q":"¿Qué pasa si una misión existe en carpeta pero no está en misiones.js?","o":["a) Para la app no existe: el catálogo es la única fuente del listado","b) Aparece igual, la app escanea carpetas","c) Aparece con datos vacíos","d) Da error al abrir la app"],"c":0},{"q":"¿Dónde viven las herramientas del maestro?","o":["a) En páginas separadas fuera del index","b) En js/tools/, una por herramienta, dentro de su vista del index","c) En el servidor de Supabase","d) Repartidas dentro de app.js"],"c":1},{"q":"¿Para qué sirve js/data/misiones.js?","o":["a) Guarda el progreso del alumno","b) Contiene el texto de las misiones","c) Es el catálogo: id, título, materia, ruta, XP e ícono de cada misión","d) Define los estilos por materia"],"c":2},{"q":"¿Cuántas secciones tiene una misión y por qué importa?","o":["a) 14 iguales en todas: la uniformidad hace que arreglar una enseñe a arreglar todas","b) Varían según el tema","c) 3, una por archivo","d) Las que quepan en la pantalla"],"c":0},{"q":"¿Qué hace que un cambio publicado llegue a un teléfono que ya tenía la app?","o":["a) Subir la versión del caché (meta-app-v47) y las etiquetas ?v=","b) Nada, llega solo al instante","c) Reinstalar el APK","d) Borrar localStorage"],"c":0},{"q":"¿Qué son las páginas satélite?","o":["a) Copias de respaldo del index","b) Páginas de publicidad","c) Entradas propias fuera del index: padres, panel docente, consulta nube, registro, camp-vivo, evaluaciones","d) Versiones viejas del sitio"],"c":2},{"q":"¿Qué relación hay entre una misión y su ficha?","o":["a) Ninguna, son proyectos distintos","b) Una ficha imprimible por misión: 57 y 57, el puente al cuaderno","c) La ficha se genera sola al abrir la misión","d) Solo las misiones traducidas tienen ficha"],"c":1},{"q":"¿Cuál es el costo asumido de no usar framework?","o":["a) Ninguno, no hay desventajas","b) Que la app no puede funcionar sin internet","c) Que no se puede publicar en Android","d) Que la uniformidad la sostienen la plantilla y los arneses, no un compilador"],"c":3}];
let qzIdx=0,qzSel=-1,qzDone=false;
function buildQz(){qzIdx=0;qzSel=-1;qzDone=false;showQz();}
function showQz(){if(qzIdx>=qzData.length){document.getElementById('qzQ').textContent='🎉 ¡Quiz completado!';document.getElementById('qzOpts').innerHTML='';fin('s-quiz');unlockAchievement('primer_quiz');return;}const q=qzData[qzIdx];document.getElementById('qzProg').textContent=`Pregunta ${qzIdx+1} de ${qzData.length}`;document.getElementById('qzQ').textContent=q.q;const opts=document.getElementById('qzOpts');opts.innerHTML='';q.o.forEach((o,i)=>{const b=document.createElement('button');b.className='qz-opt';b.textContent=o;b.onclick=()=>{if(qzDone)return;document.querySelectorAll('.qz-opt').forEach(x=>x.classList.remove('sel'));b.classList.add('sel');qzSel=i;sfx('click');};opts.appendChild(b);});qzDone=false;}
function checkQz(){if(qzSel<0)return fb('fbQz','Selecciona una respuesta.',false);qzDone=true;const opts=document.querySelectorAll('.qz-opt');if(qzSel===qzData[qzIdx].c){opts[qzSel].classList.add('correct');fb('fbQz','¡Correcto! +5 XP',true);if(!xpTracker.qz.has(qzIdx)){xpTracker.qz.add(qzIdx);pts(5);}sfx('ok');}else{opts[qzSel].classList.add('wrong');opts[qzData[qzIdx].c].classList.add('correct');fb('fbQz','Incorrecto. Revisa la respuesta correcta.',false);sfx('no');}setTimeout(()=>{qzIdx++;qzSel=-1;showQz();},1600);}
function resetQz(){sfx('click');qzIdx=0;qzSel=-1;qzDone=false;showQz();document.getElementById('fbQz').classList.remove('show');}

