function evalSwitchMode(mode){
  sfx('click');
  const cWrap=document.getElementById('evalConceptWrap'),critWrap=document.getElementById('evalCritWrap');
  const cBtn=document.getElementById('evalModeBtnConcept'),critBtn=document.getElementById('evalModeBtnCrit');
  if(mode==='crit'){
    cWrap.style.display='none';critWrap.style.display='block';
    cBtn.classList.remove('active');cBtn.setAttribute('aria-selected','false');
    critBtn.classList.add('active');critBtn.setAttribute('aria-selected','true');
    if(!window._evalCritData)genEvalCrit();
  }else{
    critWrap.style.display='none';cWrap.style.display='block';
    critBtn.classList.remove('active');critBtn.setAttribute('aria-selected','false');
    cBtn.classList.add('active');cBtn.setAttribute('aria-selected','true');
  }
}

const critCaseBank=[{"txt":"Un desarrollador revisa el repositorio y sentencia: \"Todo en un index.html con divs que se ocultan no es una arquitectura; es lo que hacíamos en 2010\"."},{"txt":"Un colega afirma: \"Tienes 57 carpetas con el mismo código repetido; eso es duplicación y es insostenible: deberías generar las misiones con plantillas\"."},{"txt":"Un ingeniero pregunta: \"Si el catálogo de misiones es un archivo JavaScript escrito a mano, ¿qué pasa cuando lleguen a 500 misiones?\"."},{"txt":"Un técnico advierte: \"Sin build step no tienes minificación ni control de dependencias; el sitio va a pesar cada vez más y nadie lo va a poder mantener\"."}];
const critCaseQuestions=["1. ¿Qué parte de la crítica es un hecho y qué parte es una interpretación equivocada?","2. ¿Qué pieza concreta del frontend responde a esta objeción?","3. Redacta tu respuesta de 3-4 frases tal como se la dirías al ingeniero.","4. ¿Qué límite real (deuda técnica honesta) reconocerías en este punto?"];
const critCaseGuides=["Los hechos suelen ser ciertos (una sola página, 57 carpetas parecidas, catálogo a mano, sin build); la interpretación falla cuando ignora el contexto: escuelas con internet pobre, mantenimiento de una sola persona y necesidad de imprimir y funcionar sin red.","Nombra la pieza exacta: switchView() y las 13 vistas; el molde de 3 archivos con sus 14 secciones; el catálogo misiones.js; la plantilla y los arneses que verifican el molde; el service worker versionado que entrega los cambios.","Respuesta modelo: reconocer el hecho, explicar la decisión con su beneficio medible (cero build, cero dependencias que caduquen, replicable en horas) y cerrar con el mecanismo que controla el riesgo (plantilla, arneses, pruebas de determinismo).","Deuda honesta: el índice del catálogo es manual, el index es grande, la duplicación del molde obliga a replicar arreglos, y la uniformidad depende de pruebas propias y no de un compilador. Se mitiga con arneses, no se niega."];

const critErrorBank=[{"txt":"\"Cada pantalla de M.E.T.A.S es una página distinta que se descarga del servidor cuando el usuario navega\".","g1":"No: las 13 vistas viven en el mismo index.html y se muestran u ocultan con switchView(), sin recarga.","g2":"Además no hay servidor que arme páginas: el sitio es estático y lo que corre es lo que está en el repositorio."},{"txt":"\"Para agregar una misión basta con crear su carpeta: la aplicación escanea el directorio y la muestra sola\".","g1":"No hay escaneo: la app lee el catálogo js/data/misiones.js, y sin entrada ahí la misión no aparece.","g2":"Crear una misión termina con dos pasos que se olvidan fácil: registrarla en el catálogo y crear su ficha imprimible."},{"txt":"\"Las misiones traducidas se traducen solas con el motor de idioma, sin escribir nada aparte\".","g1":"El motor traduce los rótulos comunes por diccionario, pero el contenido lo aporta una traducción de autor en el archivo -en.js.","g2":"Los bancos deben cuadrar índice a índice con el español, o las formas deterministas dejan de coincidir entre idiomas."},{"txt":"\"Si publico el arreglo en GitHub Pages, todos los teléfonos lo ven de inmediato\".","g1":"El service worker sirve una copia local: hasta subir el CACHE_NAME y las etiquetas ?v=, el teléfono sigue mostrando lo viejo.","g2":"Y para el APK falta además regenerar el espejo www/ antes de empaquetar."}];

const critDecisionBank=["Un desarrollador propone reemplazar el catálogo escrito a mano por un generador que arme las misiones desde una base de datos en el servidor.","Una escuela pide que cada pantalla tenga su propia dirección web para enlazarla desde WhatsApp, aunque eso obligue a recargar la aplicación en cada salto.","Un consultor recomienda meter las 57 misiones en un framework con componentes reutilizables para no repetir el molde.","Un maestro sugiere agregar una herramienta nueva copiando el archivo de otra sin registrarla en su vista del index."];
const critDecisionGuide="La decisión correcta sigue los principios de M.E.T.A.S: offline-first (el dispositivo primero, la nube como copia), costo ~$0 (Pages + Supabase Free), cero dependencias frágiles (JS puro, sin compilación), un solo código para web/PWA/APK (Capacitor) y minimización de datos de menores (códigos y claves en vez de nombres). Cada alternativa contraria agrega costo, fragilidad o riesgo sin necesidad.";

const critCompareBank=[{"a":"Un sistema repite un molde de 3 archivos por actividad y verifica el molde con pruebas propias.","b":"Un sistema genera cada actividad desde componentes de un framework con compilación.","ga":"Caso A: Replicable sin build, legible en cualquier computadora y editable sin cadena de herramientas; el precio es replicar los arreglos.","gb":"Caso B: Evita la duplicación, pero exige build, dependencias vivas y un perfil técnico para tocar cualquier detalle.","gr":"No son buenos o malos en abstracto: dependen de quién mantiene el sistema y en qué condiciones se usa."},{"a":"El catálogo de contenidos es un archivo de datos que una persona edita a mano.","b":"El catálogo se arma solo escaneando las carpetas del proyecto.","ga":"Caso A: Control total y revisable en el historial de cambios; obliga a un paso manual al crear contenido.","gb":"Caso B: Cómodo, pero exige un proceso que corra en algún lado y esconde errores hasta que algo falta.","gr":"En un sitio estático sin servidor, el archivo a mano es coherente con el resto de las decisiones."}];

const critCauseBank=[{"cause":"Se agrega una misión nueva y se olvida registrarla en js/data/misiones.js.","guide":"La carpeta existe pero la app no la muestra: para el usuario esa misión no nació. El registro en el catálogo es el paso que la hace visible."},{"cause":"Se corrige un rótulo traducido en la misión sin cambiar su clave en el diccionario del motor de idioma.","guide":"El rótulo deja de encontrarse en el diccionario y se queda en español dentro de la versión en inglés."},{"cause":"Se publica un arreglo sin subir el CACHE_NAME ni las etiquetas ?v=.","guide":"Los teléfonos siguen sirviendo la copia cacheada: el arreglo está publicado y no llega a las familias."},{"cause":"Se copia el molde de una misión sin pasar los arneses de verificación.","guide":"Los errores del molde original se replican y la uniformidad que sostiene el sistema se rompe sin que nadie lo note."}];
const critEffectBank=[{"effect":"Un arreglo de la barra de XP se aplicó una vez y quedó bien en las 57 misiones.","guide":"El molde compartido convierte un arreglo puntual en un arreglo del sistema: se corrige el patrón y se replica."},{"effect":"Una misión nueva estuvo lista en horas, con su ficha y su evaluación.","guide":"Copiar el molde de 3 archivos y cambiar los bancos evita rehacer la estructura: la parte lenta es el contenido, no la ingeniería."},{"effect":"La misma migaja de pan y la misma regla de la flecha funcionan en Mi aula y en el Campeonísimo.","guide":"Una convención de navegación escrita en la hoja de estilos común se lleva de una herramienta a otra sin reescribir nada."},{"effect":"Al abrir la aplicación en modo avión, el alumno pudo trabajar una misión completa.","guide":"El service worker guardó la copia local del sitio y el progreso quedó en localStorage: el frontend no depende de la red."}];

function genEvalCrit(){
  sfx('click');
  const cf=evalCritFormNum;window._currentEvalCritForm=cf;evalCritFormNum=(evalCritFormNum%10)+1;saveProgress();
  document.getElementById('evalcrit-screen-title').textContent=`🧠 Pensamiento Crítico · Forma ${cf} · El frontend de M.E.T.A.S`;
  evalCritAnsVisible=false;
  const out=document.getElementById('evalCritOut');out.innerHTML='';

  const kase=_pick(critCaseBank,1)[0];
  const s1=document.createElement('div');
  s1.innerHTML=`<div class="eval-section-title">I. Caso de análisis: la interpelación del ingeniero <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${kase.txt}</div>${critCaseQuestions.map((q,i)=>`<div class="crit-q-block"><div class="crit-q-label">${q}</div><textarea class="crit-textarea" rows="2" aria-label="${q}"></textarea><div class="crit-pauta">${critCaseGuides[i]}</div></div>`).join('')}<div class="crit-selfscore"><label for="critScore0">Obtenido:</label><input type="number" id="critScore0" class="crit-score-input" data-score="0" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s1);

  const err=_pick(critErrorBank,1)[0];
  const s2=document.createElement('div');
  s2.innerHTML=`<div class="eval-section-title">II. Corrige el error <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${err.txt}</div><p style="font-size:0.85rem;margin-bottom:0.5rem;">Identifica <strong>dos errores</strong> y corrígelos con tus propias palabras:</p><div class="crit-q-block"><div class="crit-q-label">Error 1 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 1 y su corrección"></textarea><div class="crit-pauta">${err.g1}</div></div><div class="crit-q-block"><div class="crit-q-label">Error 2 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 2 y su corrección"></textarea><div class="crit-pauta">${err.g2}</div></div><div class="crit-selfscore"><label for="critScore1">Obtenido:</label><input type="number" id="critScore1" class="crit-score-input" data-score="1" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s2);

  const dec=_pick(critDecisionBank,1)[0];
  const s3=document.createElement('div');
  s3.innerHTML=`<div class="eval-section-title">III. Toma de decisiones: arquitectura <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${dec}</div><div class="crit-q-block"><div class="crit-q-label">¿Qué le recomendarías hacer según los principios de arquitectura de M.E.T.A.S, y por qué sería mejor que el plan descrito?</div><textarea class="crit-textarea" rows="4" aria-label="Recomendación y justificación"></textarea><div class="crit-pauta">${critDecisionGuide}</div></div><div class="crit-selfscore"><label for="critScore2">Obtenido:</label><input type="number" id="critScore2" class="crit-score-input" data-score="2" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s3);

  const cmp=_pick(critCompareBank,1)[0];
  const s4=document.createElement('div');
  s4.innerHTML=`<div class="eval-section-title">IV. Comparación razonada <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-compare-grid"><div class="crit-compare-box"><h5>Caso A</h5>${cmp.a}</div><div class="crit-compare-box"><h5>Caso B</h5>${cmp.b}</div></div><div class="crit-q-block"><div class="crit-q-label">1. ¿Cómo calificarías cada caso según los conceptos del panorama técnico? 2. ¿Por qué no son el mismo caso?</div><textarea class="crit-textarea" rows="4" aria-label="Comparación razonada de los casos A y B"></textarea><div class="crit-pauta">Caso A: ${cmp.ga} · Caso B: ${cmp.gb} · ${cmp.gr}</div></div><div class="crit-selfscore"><label for="critScore3">Obtenido:</label><input type="number" id="critScore3" class="crit-score-input" data-score="3" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s4);

  const causes=_pick(critCauseBank,2),effects=_pick(critEffectBank,3);
  let ceRows='';
  causes.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Causa</span>${it.cause}</div><div class="crit-ce-cell"><span class="crit-ce-tag">Efecto</span><textarea class="crit-textarea" rows="2" aria-label="Efecto de: ${it.cause}" placeholder="Escribe el efecto..."></textarea></div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  effects.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell"><span class="crit-ce-tag">Causa</span><textarea class="crit-textarea" rows="2" aria-label="Causa de: ${it.effect}" placeholder="Escribe la causa..."></textarea></div><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Efecto</span>${it.effect}</div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  const s5=document.createElement('div');
  s5.innerHTML=`<div class="eval-section-title">V. Análisis de causas y efectos <span class="eval-pts">20 pts</span></div><div class="eval-item">${ceRows}<div class="crit-selfscore"><label for="critScore4">Obtenido:</label><input type="number" id="critScore4" class="crit-score-input" data-score="4" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s5);

  window._evalCritData={kase,err,dec,cmp,causes,effects};
  const totalPanel=document.createElement('div');totalPanel.id='evalCritTotalResult';totalPanel.className='crit-total-panel';totalPanel.innerHTML='<strong>🧮 Autoevaluación:</strong> responde cada sección, compara con la <em>Pauta</em> y anota tu puntaje (0–20) en cada casilla. Luego presiona <em>Calcular Total</em>.';out.appendChild(totalPanel);
  fin('s-evaluacion');
}
function toggleEvalCritAns(){evalCritAnsVisible=!evalCritAnsVisible;document.querySelectorAll('#evalCritOut .crit-pauta').forEach(el=>el.style.display=evalCritAnsVisible?'block':'none');sfx('click');}
function calcCritTotal(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  let total=0;
  document.querySelectorAll('#evalCritOut .crit-score-input').forEach(inp=>{let v=parseInt(inp.value)||0;v=Math.max(0,Math.min(20,v));inp.value=v;total+=v;});
  const panel=document.getElementById('evalCritTotalResult');
  if(panel){panel.className='crit-total-panel '+(total>=70?'eval-auto-pass':'eval-auto-risk');panel.innerHTML=`<strong>Puntaje total autoevaluado: ${total}/100</strong><br><em>Compara siempre tus respuestas con la Pauta antes de anotar el puntaje de cada sección.</em>`;}
  const formKey='crit_'+(window._currentEvalCritForm||1);
  if(total>=70){if(!xpTracker.wgt.has(formKey)){xpTracker.wgt.add(formKey);pts(8);}showToast('🎯 Pensamiento crítico: '+total+'/100');}
  else showToast('🧮 Puntaje registrado: '+total+'/100. ¡Sigue practicando!');
}
function printEvalCrit(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  const forma=window._currentEvalCritForm||1;const d=window._evalCritData;
  const lines=(n)=>Array(n).fill('<div class="ln"></div>').join('');
  let s1=`<div class="sec-title"><span>I. Caso de análisis: la interpelación del ingeniero</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.kase.txt}</p>`;
  critCaseQuestions.forEach(q=>{s1+=`<p class="crit-print-q">${q}</p>${lines(1)}`;});
  let s2=`<div class="sec-title"><span>II. Corrige el error</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.err.txt}</p><p class="crit-print-q">Identifica dos errores y corrígelos con tus propias palabras:</p><p class="crit-print-q"><strong>Error 1:</strong></p>${lines(1)}<p class="crit-print-q"><strong>Error 2:</strong></p>${lines(1)}`;
  let s3=`<div class="sec-title"><span>III. Toma de decisiones: arquitectura</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.dec}</p><p class="crit-print-q">¿Qué le recomendarías hacer según los principios de arquitectura de M.E.T.A.S, y por qué sería mejor que el plan descrito?</p>${lines(2)}`;
  let s4=`<div class="sec-title"><span>IV. Comparación razonada</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><div class="crit-compare-print-grid"><div class="crit-compare-print-box"><strong>Caso A:</strong> ${d.cmp.a}</div><div class="crit-compare-print-box"><strong>Caso B:</strong> ${d.cmp.b}</div></div><p class="crit-print-q">1. ¿Cómo calificarías cada caso según los conceptos del panorama técnico? 2. ¿Por qué no son el mismo caso?</p>${lines(2)}`;
  let ceTbl='<table class="crit-print-tbl"><tr><th>Causa</th><th>Efecto</th></tr>';
  d.causes.forEach(it=>{ceTbl+=`<tr><td>${it.cause}</td><td></td></tr>`;});
  d.effects.forEach(it=>{ceTbl+=`<tr><td></td><td>${it.effect}</td></tr>`;});
  ceTbl+='</table>';
  let s5=`<div class="sec-title"><span>V. Análisis de causas y efectos</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div>${ceTbl}`;
  let pR='';
  pR+=`<div class="p-sec"><div class="p-ttl">I. Caso</div>${critCaseQuestions.map((q,i)=>`<div class="p-crit-line"><strong>${i+1}.</strong> ${critCaseGuides[i]}</div>`).join('')}</div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">II. Corrige el error</div><div class="p-crit-line"><strong>Error 1:</strong> ${d.err.g1}</div><div class="p-crit-line"><strong>Error 2:</strong> ${d.err.g2}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">III. Toma de decisiones</div><div class="p-crit-line">${critDecisionGuide}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">IV. Comparación</div><div class="p-crit-line"><strong>Caso A:</strong> ${d.cmp.ga}</div><div class="p-crit-line"><strong>Caso B:</strong> ${d.cmp.gb}</div><div class="p-crit-line">${d.cmp.gr}</div></div>`;
  pR+=`<div class="p-sec" style="grid-column:1/-1;"><div class="p-ttl">V. Causas y efectos</div>${d.causes.map(it=>`<div class="p-crit-line"><strong>Causa:</strong> ${it.cause} → <strong>Efecto:</strong> ${it.guide}</div>`).join('')}${d.effects.map(it=>`<div class="p-crit-line"><strong>Efecto:</strong> ${it.effect} → <strong>Causa:</strong> ${it.guide}</div>`).join('')}</div>`;
  const doc=`<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>Pensamiento Crítico El frontend de M.E.T.A.S · Forma ${forma}</title><style>*{margin:0;padding:0;box-sizing:border-box;}body{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#111;background:#fff;padding:1mm 5mm;}.ph{margin-bottom:0.3rem;}.ph h2{font-size:11pt;font-weight:700;text-align:center;margin-bottom:0.2rem;}.ph-line{display:flex;align-items:baseline;gap:5px;margin-bottom:3px;}.ph-fill{flex:1;border-bottom:1px solid #555;min-height:12px;display:block;}.ph-m{display:inline-block;min-width:80px;border-bottom:1px solid #555;}.ph-s{display:inline-block;min-width:52px;border-bottom:1px solid #555;}.ph-xs{display:inline-block;min-width:36px;border-bottom:1px solid #555;}.ph-crit{font-size:9.5pt;text-align:center;color:#555;margin-top:0.1rem;}.sec-title{font-size:10.5pt;font-weight:700;padding:0.1rem 0.4rem;margin:0.2rem 0 0.1rem;display:flex;justify-content:space-between;align-items:center;border-left:4px solid #3b3a86;background:#ece9fb;color:#3b3a86;}.obt-row{display:flex;align-items:baseline;gap:4px;font-size:9.5pt;font-weight:700;font-style:italic;color:#3b3a86;}.obt-lbl{white-space:nowrap;}.obt-line{display:inline-block;min-width:50px;border-bottom:1.5px solid #3b3a86;height:12px;}.obt-pct{white-space:nowrap;}.crit-print-scenario{font-size:10.5pt;background:#ece9fb;border-left:3px solid #3b3a86;padding:0.2rem 0.5rem;margin:0.1rem 0 0.2rem;line-height:1.3;}.crit-print-q{font-size:10pt;font-weight:600;margin:0.15rem 0 0.08rem;line-height:1.25;}.ln{border-bottom:1px solid #111;min-height:12px;margin-bottom:2px;}.crit-compare-print-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.5rem;margin:0.15rem 0;}.crit-compare-print-box{font-size:9.5pt;background:#ece9fb;border-radius:4px;padding:0.25rem 0.4rem;line-height:1.25;}.crit-print-tbl{width:100%;border-collapse:collapse;font-size:9.5pt;margin-top:0.15rem;}.crit-print-tbl th,.crit-print-tbl td{border:1px solid #999;padding:0.3rem 0.45rem;text-align:left;height:30px;vertical-align:middle;}.crit-print-tbl th{background:#ece9fb;}.pauta-wrap{page-break-before:always;padding-top:0.4rem;}.p-head{border-bottom:2px solid #333;padding-bottom:0.3rem;margin-bottom:0.4rem;text-align:center;}.p-main{font-size:9.5pt;font-weight:700;}.p-sub{font-size:7pt;color:#c00;font-weight:700;margin:0.08rem 0;}.p-meta{font-size:7pt;color:#555;}.p-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.4rem 0.9rem;}.p-sec{border:1px solid #ccc;border-radius:4px;padding:0.3rem 0.45rem;}.p-ttl{font-size:8pt;font-weight:700;border-bottom:1px solid #ddd;padding-bottom:0.1rem;margin-bottom:0.18rem;}.p-crit-line{font-size:7.5pt;color:#007a00;margin-bottom:0.18rem;line-height:1.35;}.total-row{display:flex;align-items:baseline;justify-content:flex-start;margin-left:20%;gap:7px;font-size:11pt;font-weight:700;font-style:italic;margin-top:0.2rem;padding:0.1rem 0;color:#3b3a86;}.total-row .obt-line{min-width:80px;border-bottom:1.5px solid #3b3a86;}.forma-tag{position:fixed;bottom:5mm;right:6mm;font-size:7pt;color:#555;border:1px solid #bbb;padding:1px 5px;border-radius:3px;background:white;}@media print{@page{size:letter portrait;margin:12.7mm;}}</style></head><body><div class="ph"><h2>Evaluación Competencial · Pensamiento Crítico · El frontend de M.E.T.A.S · Autocapacitación Técnica</h2><div class="ph-line"><strong>Nombre:</strong><span class="ph-fill">&nbsp;</span><strong>Fecha:</strong><span class="ph-m">&nbsp;</span></div><div class="ph-line"><strong>Institución:</strong><span class="ph-fill">&nbsp;</span><strong>Grado y Sección:</strong><span class="ph-s">&nbsp;</span><strong>Nº Lista:</strong><span class="ph-xs">&nbsp;</span></div><p class="ph-crit">Valor total: 100 puntos · 5 secciones de 20 puntos</p></div>${s1}${s2}${s3}${s4}${s5}<div class="total-row"><span>Total, obtenido</span><span class="obt-line"></span><span>de 100</span></div><div class="pauta-wrap"><div class="p-head"><div class="p-main">✅ PAUTA: Pensamiento Crítico · El frontend de M.E.T.A.S · Forma ${forma}</div><div class="p-sub">Documento exclusivo del docente · No distribuir al estudiante</div><div class="p-meta">Valor total: 100 pts | 5 secciones × 20 pts c/u, respuesta abierta, usar como guía de corrección</div></div><div class="p-grid">${pR}</div></div><div class="forma-tag">Forma ${forma}</div></body></html>`;
  const win=window.open('','_blank','');
  if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}
  win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);
}

// ===================== LÍNEA DE TIEMPO INTERACTIVA =====================
const timelineData=[{"y":"1","icon":"🏠","label":"index.html: la puerta","text":"Una sola página con <strong>13 vistas</strong> (inicio, misiones, rutas, progreso, ajustes, padre, Zona Docente, Mi aula, gobierno, plan de acción, parte mensual, Campeonísimo y collage). Se muestran y ocultan; no hay recargas."},{"y":"2","icon":"⚙️","label":"js/app.js: el director","text":"Navegación con <strong>switchView()</strong>, pintado del catálogo, filtros por materia y ciclo, arranque de cada herramienta y guardado del progreso. Es el archivo que más se toca."},{"y":"3","icon":"🗃️","label":"js/data: los bancos","text":"Ocho archivos de datos puros: <strong>misiones.js</strong> (catálogo), campeonismo-bank, dcnb-map, diagnosticos, consejos-padres, frases, paises y proceres. Datos separados de la lógica."},{"y":"4","icon":"🧰","label":"js/tools: el maestro","text":"Siete herramientas: plan-accion, registros-admin (Mi aula), campeonismo, gobierno-escolar, parte-mensual, collage-maker y pwa-install. Cada una vive dentro de su vista del index."},{"y":"5","icon":"📐","label":"misiones/: el molde","text":"<strong>57 carpetas</strong>, cada una con su HTML, su JS y su CSS, y un <strong>-en.js</strong> si está traducida. Catorce secciones iguales en todas: reparar una enseña a reparar todas."},{"y":"6","icon":"🖨️","label":"fichas/: el papel","text":"Una ficha imprimible por misión (57), más su índice y el mapa curricular DCNB. Lo que se hace en pantalla también se puede repartir en el aula sin electricidad."},{"y":"7","icon":"🛰️","label":"Páginas satélite","text":"padres.html, panel-docente.html, consulta-nube.html, registro.html, camp-vivo.html, evaluaciones.html y mision.html: entradas propias para públicos que no pasan por el index."},{"y":"8","icon":"🧱","label":"Capas comunes","text":"metas-registro, metas-dialogos, metas-presentacion, metas-supabase, metas-docente-sync y metas-i18n: lo que todas las pantallas comparten para no repetirse."}];
function initTimeline(){const track=document.getElementById('timelineTrack');if(!track)return;timelineData.forEach((d,i)=>{const b=document.createElement('button');b.className='tl-node';b.type='button';b.dataset.idx=i;b.innerHTML=`<span class="tl-dot">${d.icon}</span><span class="tl-year">${d.y}</span><span class="tl-label">${d.label}</span>`;b.onclick=()=>showTimeline(i);track.appendChild(b);});}
function showTimeline(i){const d=timelineData[i];document.querySelectorAll('.tl-node').forEach(n=>n.classList.remove('tl-active'));document.querySelector(`.tl-node[data-idx="${i}"]`).classList.add('tl-active');document.getElementById('tlInfoIcon').textContent=d.icon;document.getElementById('tlInfoText').innerHTML=`<strong>${d.y} · ${d.label}.</strong> ${d.text}`;document.getElementById('tlInfo').style.display='flex';sfx('click');}

// ===================== SIMULACIÓN: MÉTODO DE POPPER =====================
let methodRunning=false;
function startMethod(){if(methodRunning)return;methodRunning=true;sfx('click');document.getElementById('methodBtn').style.display='none';document.getElementById('methodBranch').classList.remove('show');document.getElementById('methodResult').innerHTML='';const steps=['ms1','ms2','ms3','ms4'];const arrows=['ma1','ma2','ma3'];steps.forEach(s=>document.getElementById(s).classList.remove('active','done'));arrows.forEach(a=>document.getElementById(a).classList.remove('active'));let i=0;function next(){if(i>0){document.getElementById(steps[i-1]).classList.remove('active');document.getElementById(steps[i-1]).classList.add('done');}if(i<steps.length){if(i>0)document.getElementById(arrows[i-1]).classList.add('active');document.getElementById(steps[i]).classList.add('active');sfx('ok');i++;setTimeout(next,900);}else{document.getElementById('methodBranch').classList.add('show');}}next();}
function resolveMethod(conInternet){sfx(conInternet?'ok':'no');document.getElementById('methodBranch').classList.remove('show');document.getElementById('ms4').classList.remove('active');document.getElementById('ms4').classList.add('done');const r=document.getElementById('methodResult');if(conInternet){r.innerHTML='<div class="method-step done" style="opacity:1;"><span class="ms-num">5</span><span class="ms-icon">🌐</span><span class="ms-text"><strong>Traducción de autor:</strong> la misión carga su archivo -en.js y en el catálogo aparece el distintivo 🌐 EN.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">🧪</span><span class="ms-text"><strong>Bancos índice a índice:</strong> el motor de idioma cambia los rótulos comunes y las formas de la evaluación coinciden en los dos idiomas.</span></div>';}else{r.innerHTML='<div class="method-step done" style="opacity:1;border-color:var(--red);background:var(--red-gl);"><span class="ms-num">5</span><span class="ms-icon">🇭🇳</span><span class="ms-text"><strong>Solo en español:</strong> sin archivo -en.js no se pinta el distintivo y el motor de idioma no interviene. La misión funciona igual.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">📋</span><span class="ms-text"><strong>Queda en la cola de traducción:</strong> el molde ya está listo para recibir su -en.js cuando le toque el turno.</span></div>';}methodRunning=false;document.getElementById('methodBtn').style.display='inline-flex';document.getElementById('methodBtn').textContent='🔄 Repetir simulación';sfx('fan');}

// ===================== LABORATORIO DE CONCEPTOS =====================
const parteData={"portada":{"nombre":"index.html (la portada)","icon":"🏠","estructura":{"title":"Qué es","info":"• La aplicación <strong>entera</strong> en un archivo<br>• <strong>13 vistas</strong> (<code>div class=\"view\"</code>) que se muestran y ocultan<br>• Portada, misiones, rutas, progreso, ajustes y padres<br>• Zona Docente con Mi aula, gobierno, plan, parte, Campeonísimo y collage"},"funcion":{"title":"Cómo funciona","info":"• <strong>switchView()</strong> apaga la vista activa y enciende otra<br>• No hay recarga ni URL nueva: el estado vive en memoria y localStorage<br>• Cada vista arranca su herramienta al abrirse<br>• Los scripts se piden con <code>?v=47</code> para renovar el caché"},"enfermedades":{"title":"Riesgos y límites","info":"• Un solo archivo grande: hay que buscar con disciplina<br>• Si una vista no existe, el botón que la llama no hace nada<br>• Sin router de verdad, no hay enlace directo a una vista interna<br>• Cargar todo de una vez pesa más en la primera visita"},"cuidados":{"title":"Ejemplo real","info":"• La Zona Docente se reordenó (primero entrar, el registro abajo y plegado) sin tocar ninguna otra vista<br>• La flecha del encabezado sube un nivel y dentro del contenido no va ninguna: regla de la casa"}},"mision":{"nombre":"Una misión (el molde)","icon":"📐","estructura":{"title":"Qué es","info":"• Carpeta propia en <code>misiones/</code><br>• Tres archivos: <strong>HTML</strong>, <strong>js/</strong> y <strong>css/</strong> de la misión<br>• Un cuarto, <strong>-en.js</strong>, si tiene traducción de autor<br>• <strong>14 secciones</strong> iguales en las 57 misiones"},"funcion":{"title":"Cómo funciona","info":"• El HTML trae las secciones; el JS trae los bancos y el motor de actividades<br>• El progreso y el XP se guardan con una clave propia en localStorage<br>• La barra de XP, el botón de WhatsApp y el distintivo 🌐 EN son comunes<br>• La evaluación arma formas deterministas a partir del banco"},"enfermedades":{"title":"Riesgos y límites","info":"• Copiar el molde también copia los errores: por eso existen los arneses<br>• Si el banco en inglés no cuadra índice a índice, las formas dejan de coincidir<br>• Una misión fuera del catálogo no aparece aunque su carpeta esté completa<br>• Cambiar un rótulo traducido obliga a cambiar también su clave en el motor de idioma"},"cuidados":{"title":"Ejemplo real","info":"• La barra de XP desbordaba la pantalla del teléfono en las 57 misiones: se arregló una vez en el molde y se replicó<br>• Las rutas de Código y Robots nacieron copiando el molde y cambiando bancos y color"}},"tools":{"nombre":"js/tools (el maestro)","icon":"🧰","estructura":{"title":"Qué es","info":"• <strong>Siete herramientas</strong>: plan-accion, registros-admin, campeonismo, gobierno-escolar, parte-mensual, collage-maker y pwa-install<br>• Cada una es un archivo con su vista en el index<br>• Viven detrás de la cuenta docente"},"funcion":{"title":"Cómo funciona","info":"• app.js llama a la función de arranque de cada herramienta al abrir su vista<br>• Guardan en localStorage y, cuando toca, suben a la nube por RPC<br>• Comparten los diálogos y la presentación comunes<br>• El Campeonísimo trae su propio banco en js/data"},"enfermedades":{"title":"Riesgos y límites","info":"• Son las piezas más grandes del proyecto: crecen rápido<br>• Un cambio de navegación en una puede confundir si no se repite en las otras<br>• Dependen de la sesión docente: sin cuenta no hay escritura"},"cuidados":{"title":"Ejemplo real","info":"• Mi aula y el Campeonísimo comparten hoy la misma migaja de pan (.nav-ruta) y la misma regla de la flecha, que nació en una y se llevó a la otra"}},"capas":{"nombre":"Capas comunes (js/)","icon":"🧱","estructura":{"title":"Qué es","info":"• <strong>app.js</strong>: navegación y catálogo<br>• <strong>metas-registro</strong>: cuenta y sesión<br>• <strong>metas-dialogos</strong>: cuadros propios en vez de alert()<br>• <strong>metas-presentacion</strong>, <strong>metas-supabase</strong>, <strong>metas-docente-sync</strong> y <strong>metas-i18n</strong>"},"funcion":{"title":"Cómo funciona","info":"• Se cargan una vez en el index y quedan disponibles para todas las vistas<br>• Las misiones cargan solo las que necesitan (i18n, diálogos)<br>• Cambiar aquí cambia el comportamiento en todo el sistema"},"enfermedades":{"title":"Riesgos y límites","info":"• Tocar una capa común tiene alcance total: se prueba con arneses antes de publicar<br>• Un rótulo con guion largo dentro del diccionario rompe la traducción si no se cambia a la vez que la misión"},"cuidados":{"title":"Ejemplo real","info":"• El diccionario de metas-i18n usa el texto español exacto como clave: al quitar los guiones largos hubo que cambiar misión y clave a la vez para no perder la traducción"}}};
let labParte='portada',labAspecto='estructura';
function labShowParte(parteKey){labParte=parteKey;updateLabDisplay();document.querySelectorAll('.lab-cont-btn').forEach(b=>b.classList.remove('active-pri'));const btn=document.querySelector(`[data-parte="${parteKey}"]`);if(btn)btn.classList.add('active-pri');if(typeof sfx==='function')sfx('click');}
function labShowAspecto(aspectoKey){labAspecto=aspectoKey;updateLabDisplay();document.querySelectorAll('.lab-asp-btn').forEach(b=>b.classList.remove('active-sec'));const btn=document.querySelector(`[data-aspecto="${aspectoKey}"]`);if(btn)btn.classList.add('active-sec');if(typeof sfx==='function')sfx('click');}
function updateLabDisplay(){const data=parteData[labParte];const asp=data[labAspecto];document.getElementById('lab-sentence').innerHTML=`🦉 Explorando: <strong>${data.nombre}</strong> → <strong>${asp.title}</strong>`;document.getElementById('lab-display').innerHTML=`<div class="lab-cont-header">${data.icon} ${data.nombre}</div><div class="lab-asp-title">${asp.title}</div><div class="lab-asp-info">${asp.info}</div>`;}

// ===================== DIPLOMA =====================
function _diplPct(){return xp>=MXP?100:Math.round((xp/MXP)*100);}
function openDiploma(){sfx('fan');const pct=_diplPct();document.getElementById('diplPct').textContent=pct+'%';document.getElementById('diplBar').style.width=pct+'%';document.getElementById('diplDate').textContent='Fecha: '+new Date().toLocaleDateString('es-HN',{year:'numeric',month:'long',day:'numeric'});const msgs=['¡Sigue estudiando tu sistema!','¡Muy buen trabajo!','¡Excelente arquitecto en formación!','¡Dominas el panorama de M.E.T.A.S!','¡Maestro del Panorama Técnico!'];document.getElementById('diplMsg').textContent=msgs[Math.min(Math.floor(pct/25),4)];const stars=['⭐','⭐⭐','⭐⭐⭐'];document.getElementById('diplStars').textContent=stars[Math.min(Math.floor(pct/40),2)];const achTxt=unlockedAch.map(id=>ACHIEVEMENTS[id].icon+' '+ACHIEVEMENTS[id].label).join(' · ');document.getElementById('diplAch').textContent=achTxt||'Sigue completando secciones para desbloquear logros';document.getElementById('diplomaOverlay').classList.add('open');launchConfetti();}
function closeDiploma(){document.getElementById('diplomaOverlay').classList.remove('open');}
function updateDiplomaName(v){document.getElementById('diplName').textContent=v||'Estudiante';}
function shareWA(){const name=document.getElementById('diplName').textContent||'Estudiante';const pct=_diplPct();const msg='🏗️ ¡'+name+' completó el Módulo 1 de Autocapacitación M.E.T.A.S (Panorama técnico)! 🏅 Progreso: '+pct+'% · ⚙️ policastsapien.com';window.open('https://wa.me/?text='+encodeURIComponent(msg),'_blank');}
async function captureDiploma(){if(typeof html2canvas==='undefined'){showToast('⚠️ Cargando... intenta de nuevo');return;}sfx('click');const card=document.querySelector('.diploma-card');const btn=document.querySelector('.diploma-actions .btn-pri');const toHide=[card.querySelector('.diploma-input'),card.querySelector('.diploma-actions'),card.querySelector('hr')];if(btn){btn.disabled=true;btn.textContent='⏳ Capturando...';}toHide.forEach(el=>{if(el)el.style.display='none';});let dataUrl='';try{const canvas=await html2canvas(card,{scale:2,useCORS:true,backgroundColor:'#ffffff'});toHide.forEach(el=>{if(el)el.style.display='';});dataUrl=canvas.toDataURL('image/png');const name=(document.getElementById('diplName').textContent||'Estudiante').replace(/\s+/g,'-');const fileName='constancia-'+name+'.png';const cap=window.Capacitor;if(cap&&cap.isNativePlatform&&cap.isNativePlatform()&&cap.Plugins?.Filesystem&&cap.Plugins?.Share){const base64Data=dataUrl.split(',')[1];const result=await cap.Plugins.Filesystem.writeFile({path:fileName,data:base64Data,directory:'CACHE'});await cap.Plugins.Share.share({url:result.uri,dialogTitle:'Guardar / Compartir Constancia'});}else{const a=document.createElement('a');a.href=dataUrl;a.download=fileName;a.click();}}catch(e){toHide.forEach(el=>{if(el)el.style.display='';});if(e.name!=='AbortError')showToast('⚠️ No se pudo guardar la constancia');}finally{if(btn){btn.disabled=false;btn.textContent='📷 Guardar foto';}}}

